// Writes src/engine/config/catalog.ts, which bundles every site's rules in
// src/engine/config/sites/*.json. Run after adding or removing a site file:
//   node scripts/site-catalog.mjs
import { readdirSync, writeFileSync } from "node:fs";

const dir = new URL("../src/engine/config/", import.meta.url);
const files = readdirSync(new URL("sites/", dir)).filter((file) => file.endsWith(".json")).sort();
const name = (file) => file.replace(/\.json$/, "").replace(/-(\w)/g, (_, c) => c.toUpperCase());
const lines = [
  "// Generated by scripts/site-catalog.mjs from sites/*.json; do not edit.",
  'import type { SiteConfig, GlobalConfig } from "./schema";',
  'import globalsData from "./globals.json";',
  ...files.map((file) => `import ${name(file)} from "./sites/${file}";`),
  "",
  `export const configs = [${files.map(name).join(", ")}] as unknown as SiteConfig[];`,
  "export const globals = globalsData as GlobalConfig;",
  "",
];
writeFileSync(new URL("catalog.ts", dir), lines.join("\n"));
console.log(`catalog.ts: ${files.length} sites`);
